    ctx.fillStyle = `rgba(${v},${v + 2},${v + 6},${rng.range(0.25, 0.7)})`;
    const x = rng.range(0, size);
    const y = rng.range(0, size);
    const r = rng.range(0.4, 1.9);
    ctx.fillRect(x, y, r, r);
