          paint.box(lines[a] + 3.4, 0.028, (from + to) / 2, 0.06, 0.01, (to - from) / 2 - 1.2, 0x5e5d58, { faces: 'top' });
          paint.box(lines[a] - 3.4, 0.028, (from + to) / 2, 0.06, 0.01, (to - from) / 2 - 1.2, 0x5e5d58, { faces: 'top' });
        } else {
