    const names = ['MOTEL', 'DINER', 'LIQUOR', 'PAWN', 'BAIT', 'TATTOO', 'NOODLE', 'GARAGE'];
    const words = ['OPEN LATE', 'COLD BEER', 'CASH ONLY', 'PIER 9', 'SEA FOOD', 'VACANCY'];
    const sy = y0 + rng.range(4.0, Math.min(7.5, h - 1));
